const intro=document.createElement('div');intro.className='onboard';intro.id='onboard';document.body.appendChild(intro);let signup={},profilePic='',carPic='',insurancePic='';function onboarding(step){if(step===0){intro.innerHTML=`<div class="onboard-box"><div class="brand"><span>↗</span>ridelink</div><div class="eyebrow" style="margin-top:28px">WELCOME TO RIDELINK</div><h1>Let’s get you started.</h1><p class="sub">A better way to get there, together.</p><div class="field"><label>FULL NAME</label><input id="onName" placeholder="Your name"></div><div class="field"><label>STUDENT EMAIL</label><input id="onEmail" type="email" placeholder="you@college.edu"></div><button class="primary" id="onNext">Continue →</button><p class="note">Demo: email format is checked, but no verification email is sent.</p></div>`;$('onNext').onclick=()=>{let name=$('onName').value.trim(),email=$('onEmail').value.trim();if(!name||!/^\S+@\S+\.edu$/i.test(email)){alert('Please enter your name and a valid .edu email.');return}signup={name,email};onboarding(1)}}else if(step===1){intro.innerHTML=`<div class="onboard-box"><div class="eyebrow">STEP 2 OF 3</div><h1>How will you ride?</h1><p class="sub">Choose the experience that fits you.</p><button class="primary" id="riderRole">I need a ride →</button><button class="secondary" id="driverRole">I’m a driver →</button><button class="secondary" id="onBack">Back</button></div>`;$('riderRole').onclick=()=>{signup.role='student';onboarding(2)};$('driverRole').onclick=()=>{signup.role='driver';onboarding(2)};$('onBack').onclick=()=>onboarding(0)}else{intro.innerHTML=`<div class="onboard-box"><div class="eyebrow">STEP 3 OF 3</div><h1>${signup.role==='driver'?'Your driver profile':'Your rider profile'}</h1><p class="sub">Tell other students a little about yourself.</p><div class="field"><label>COLLEGE</label><input id="onCollege" list="colleges" placeholder="Start typing your college"></div><div class="field"><label>YEAR IN COLLEGE</label><select id="onYear"><option>First year</option><option>Sophomore</option><option>Junior</option><option>Senior</option><option>Graduate student</option></select></div><div class="field"><label>PROFILE PHOTO (REQUIRED)</label><input type="file" accept="image/*" id="onPhoto"></div>${signup.role==='driver'?`<div class="field"><label>CAR MAKE AND MODEL</label><input id="onCar" placeholder="Toyota RAV4"></div><div class="field"><label>CAR COLOR</label><input id="onColor" placeholder="Silver"></div><div class="field"><label>CAR PHOTO (REQUIRED)</label><input type="file" accept="image/*" id="onCarPhoto"></div><div class="field"><label>INSURANCE PHOTO</label><input type="file" accept="image/*" id="onInsurancePhoto"><p class="note">Demo only: the photo stays on this device and is not verified. Do not upload sensitive documents to a shared device.</p></div><p class="note">License verification needs a secure service. Please don’t upload your license to this demo.</p>`:''}<button class="primary" id="onFinish">Finish setup →</button><button class="secondary" id="onBack">Back</button><p class="note">Your profile is saved on this device only. Student verification is not connected.</p></div>`;$('onPhoto').onchange=e=>readImage(e.target,v=>profilePic=v);if(signup.role==='driver'){$('onCarPhoto').onchange=e=>readImage(e.target,v=>carPic=v);$('onInsurancePhoto').onchange=e=>readImage(e.target,v=>insurancePic=v)}$('onBack').onclick=()=>onboarding(1);$('onFinish').onclick=()=>{let college=$('onCollege').value.trim();if(!college||!profilePic||(signup.role==='driver'&&(!$('onCar').value.trim()||!$('onColor').value.trim()||!carPic))){alert('Please complete the details and add the required photos.');return}signup={...signup,college,year:$('onYear').value,photo:profilePic,car:signup.role==='driver'?$('onCar').value.trim():'',color:signup.role==='driver'?$('onColor').value.trim():'',carPhoto:carPic,insurancePhoto:insurancePic,completed:true};try{localStorage.setItem('cr_profile',JSON.stringify(signup));profileData=signup;demo.role=signup.role;saveDemo();intro.classList.add('hidden');if(signup.role==='driver'){go('driver');$('dCar').value=signup.car;$('dColor').value=signup.color;carImage=signup.carPhoto}}catch(e){alert('Unable to save the photos. Try smaller images.')}}}}
if(profileData.completed)intro.classList.add('hidden');else onboarding(0);
// Safety lives with each scheduled ride.
const safetyNav=document.querySelector('[data-extra="safety"]');if(safetyNav)safetyNav.remove();
const renderTripsBase=renderTrips;renderTrips=function(){renderTripsBase();requests.filter(x=>x.status==='Booked · simulated hold'||x.status==='Completed · simulated payout').forEach(x=>{if(!x.code){x.code=String(Math.floor(100000+Math.random()*900000));localStorage.setItem('cr_requests',JSON.stringify(requests))}let buttons=[...$('tripList').querySelectorAll('button')],share=buttons.find(b=>b.getAttribute('onclick')===`go('safety')`&&b.closest('.trip-row')?.innerHTML.includes(esc(x.ride)));if(share){share.textContent='Share trip with family or friends';share.setAttribute('onclick',`shareTrip(${x.id})`)}let row=share?.closest('.trip-row');if(row)row.insertAdjacentHTML('beforeend',`<div class="verify-box"><b>Pickup code: ${x.code}</b><p>Give this demo code to your driver when they arrive. Real code verification is not connected.</p></div>`)})};

// College suggestions are optional: students may also type another school.
const colleges=['University of California, Los Angeles','University of Southern California','University of California, Berkeley','University of California, San Diego','University of California, Santa Barbara','University of California, Irvine','University of California, Davis','University of California, Santa Cruz','University of California, Riverside','University of California, Merced','Stanford University','California State University, Long Beach','San Diego State University','San Francisco State University','California Polytechnic State University, San Luis Obispo','University of San Diego','New York University','Harvard University','University of Michigan','University of Texas at Austin'];let collegeList=document.createElement('datalist');collegeList.id='colleges';collegeList.innerHTML=colleges.map(x=>`<option value="${esc(x)}"></option>`).join('');document.body.appendChild(collegeList);$('college').setAttribute('list','colleges');
const oldTripsRenderer=renderTrips;renderTrips=function(){oldTripsRenderer();let list=$('tripList');if(demo.drivers.length){let html=demo.drivers.map(r=>`<div class="trip-row"><span class="tag">Offered ride · this device</span><p><b>${esc(r.from)} → ${esc(r.to)}</b></p><p class="sub">${esc(r.date)} · ${esc(r.time)} · ${r.seats} seats · ${money(r.price)} per student</p><p class="note">Visible only on this device. Shared rides are not connected yet.</p></div>`).join('');list.insertAdjacentHTML('afterbegin','<h3>Rides you offered</h3>'+html+'<h3 style="margin-top:20px">Ride requests</h3>')}};
$('dRadius').closest('.field').insertAdjacentHTML('afterend',`<div class="field driver-map"><label>DROPOFF RADIUS PREVIEW</label><div class="map-demo" aria-label="Illustration of dropoff radius"><div class="map-street street-a"></div><div class="map-street street-b"></div><div class="map-street street-c"></div><div class="map-circle" id="driverMapCircle"></div><div class="map-pin">●</div><div class="map-label">Destination</div></div><p class="note">Illustration only; not a real map or measured distance.</p></div>`);function showDriverRadius(){let n=Math.max(1,Math.min(30,+$('dRadius').value||1));$('driverMapCircle').style.width=(45+n*3)+'px';$('driverMapCircle').style.height=(45+n*3)+'px'}$('dRadius').addEventListener('input',showDriverRadius);showDriverRadius();
